# repository; the task-server serves it to the oracle.
TS="${TASK_SERVER_URL:-http://task-server:9111}"
TS="${TS%/}"
for i in $(seq 1 30); do
  if curl -sf --max-time 60 -H "X-Submission-Token: f9f75ab8d012db675e48f5c9067682c2" "$TS/solve" > /output/poc.bin.part; then
